mapper.select:
SELECT 
FROM diary_cover_library_elements
WHERE library_item_id = #{libraryItemId}
  AND snapshot_version = #{snapshotVersion}
ORDER BY z_index ASC, id ASC

SELECT e.id, e.library_item_id, e.snapshot_version, e.element_type, e.text_content, e.image_url, e.style_type, e.color_type, e.photo_style, e.text_font, e.text_color, e.photo_share_mode, e.photo_asset_id, e.position_x, e.position_y, e.width, e.height, e.rotation, e.z_index, e.created_at, e.updated_at FROM diary_cover_library_elements e JOIN diary_cover_library_items i ON i.id = e.library_item_id WHERE e.library_item_id IN
#{itemId}
AND e.snapshot_version = i.snapshot_version ORDER BY e.library_item_id ASC, e.z_index ASC, e.id ASC
